Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "background": null,
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum.benchmark == 10000"
    },
    {
      "calculate": "datum.owner_view === ''confirmed'' ? ''Owners confirmed'' : ''Unknown counted public''",
      "as": "o"
    },
    {
      "calculate": "datum.action === datum.action_low ? ''Same'' : ''Changes''",
      "as": "res"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#FFFFFF",
        "strokeWidth": 3,
        "cursor": "pointer"
      },
      "encoding": {
        "x": {
          "field": "beyond_km",
          "type": "ordinal",
          "sort": [
            10,
            15,
            20
          ],
          "axis": {
            "orient": "top",
            "title": "Hospital limit (km)",
            "labelFont": "Segoe UI",
            "labelFontSize": 10,
            "titleFont": "Segoe UI",
            "titleFontSize": 9,
            "titleColor": "#51656F"
          }
        },
        "y": {
          "field": "o",
          "type": "nominal",
          "sort": [
            "Owners confirmed",
            "Unknown counted public"
          ],
          "axis": {
            "title": null,
            "labelFont": "Segoe UI",
            "labelFontSize": 10
          }
        },
        "color": {
          "field": "res",
          "type": "nominal",
          "scale": {
            "domain": [
              "Same",
              "Changes"
            ],
            "range": [
              "#0E6F78",
              "#E8B4AF"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "o",
            "title": "Owners"
          },
          {
            "field": "beyond_km",
            "title": "Hospital limit km"
          },
          {
            "field": "action",
            "title": "Action in this check"
          },
          {
            "field": "action_low",
            "title": "Base action"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "font": "Segoe UI",
        "fontSize": 11,
        "fontWeight": "bold"
      },
      "encoding": {
        "x": {
          "field": "beyond_km",
          "type": "ordinal",
          "sort": [
            10,
            15,
            20
          ]
        },
        "y": {
          "field": "o",
          "type": "nominal",
          "sort": [
            "Owners confirmed",
            "Unknown counted public"
          ]
        },
        "text": {
          "field": "res"
        },
        "color": {
          "condition": {
            "test": "datum.res === ''Same''",
            "value": "#FFFFFF"
          },
          "value": "#7A1F18"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    }
  }
}'

'{
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
    "strokeWidth": 3,
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "point": {
    "filled": true,
    "size": 75
  },
  "rect": {},
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "fontSize": 12,
    "fill": "#605E5C"
  },
  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelColor": "#605E5C",
    "labelFontSize": 12,
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleColor": "#0B2530",
    "titleFontSize": 16,
    "titleFontWeight": "normal"
  },
  "axisQuantitative": {
    "tickCount": 3,
    "grid": true,
    "gridColor": "#C8C6C4",
    "gridDash": [
      1,
      5
    ],
    "labelFlush": false
  },
  "axisX": {
    "labelPadding": 5
  },
  "axisY": {
    "labelPadding": 10
  },
  "header": {
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleFontSize": 16,
    "titleColor": "#0B2530",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#605E5C"
  },
  "legend": {
    "titleFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "titleFontWeight": "bold",
    "titleColor": "#605E5C",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#605E5C",
    "symbolType": "circle",
    "symbolSize": 75
  }
}'
